	"010101": {
		names: [{ nominative: "Ѡ҆брѣ́занїе гдⷭ҇а на́шегѡ і҆и҃са хрⷭ҇та̀", genitive: "Пра́здника" }],
		biographies: [
			{
				id: "bulgakov",
				copyright: "Протоиерей Сергий Булгаков. Настольная Книга.",
				text: "Ѡ҆брѣ́занїе гдⷭ҇а \nНа восьмой день после Своего Рождества Господь наш Иисус Христос, по ветхозаветному закону, принял обрезание, установленное для всех младенцев мужского пола в зна- мение Завета Бога с праотцом Авраамом и его потомками (<a href=\"bible=Gen#17:10-14\">Быт. 17, 10—14</a>; <a href=\" bible=Lev#12:3\">Лев. 12, 3</a>). При совершении этого обряда Божествен- ному Младенцу было дано Имя Иисус, возвещенное Архангелом Гавриилом еще в день Благовещения Пресвятой Деве Марии (<a href=\" bible=Lk#1:31-33,2:21\">Лк. 1, 31—33; 2, 21</a>). По толкованию отцов Церкви, Господь, Творец закона, принял обрезание, являя пример, как людям следует неукоснительно исполнять Божественные установления. Господь при- нял обрезание для того, чтобы никто впоследствии не мог усом- ниться в том, что Он был истинным Человеком, а не носителем призрачной плоти, как учили некоторые еретики (докеты). В Новом Завете обряд обрезания уступил место таинству Крещения, прооб- разом которого он являлся (<a href=\" bible=Col#2:11-12\">Кол. 2, 11-12</a>). Свидетельства о праздновании Обрезания Господня в Восточной Церкви восходят к IV веку. Канон празднику написан преподобным Стефаном Савваитом (память 28 октября). Вместе с обрезанием, воспринятым Господом как знамение Завета Бога с людьми, Он получил и Имя Иисус (Спаситель) как печать Своего служения делу спасения мира (<a href=\" bible=Mt#1:21\">Мф. 1, 21</a>; <a href=\" bible=Mk#9:38-39,16:17\">Мк. 16, 17; 9, 38, 39</a>; <a href=\" bible=Lk#10:17\">Лк. 10, 17</a>; <a href=\" bible=Acts#3:6,16\">Деян. 3, 6, 16</a>; <a href=\"bible=Philip#2:9,10\">Фил. 2, 9, 10</a>). Эти два события, совершившиеся в самом начале земной жизни Спасителя, напоминают христианам, что они всту- пили в Новый Завет с Богом и «обрезаны обрезанием нерукотворенным, совлечением греховного тела плоти, обрезанием Христовым» (<a href=\" bible=Col#2:11\">Кол. 2, 11</a>). Само имя христианина свидетельствует о вступлении человека в Новый Завет с Богом.",
			},
		],
		info: [],
		refs: [],
		services: [
			{
				type: "8",
				hymns: [],
				sections: [
					{
						section: "liturgy",
						items: [
							{
								kind: "troparion",
								text: "На прⷭ҇то́лѣ ѻ҆гнезра́чнѣмъ въ вы́шнихъ сѣдѧ́й со ѻ҆ц҃е́мъ безнача́льнымъ, и҆ бж҃е́ственнымъ твои́мъ дх҃омъ, бл҃говоли́лъ є҆сѝ роди́тисѧ на землѝ ѿ ѻ҆трокови́цы, неискꙋсомꙋ́жныѧ твоеѧ̀ мт҃ре, і҆и҃се: сегѡ̀ ра́ди и҆ ѡ҆брѣ́занъ бы́лъ є҆сѝ ꙗ҆́кѡ человѣ́къ ѻ҆смодне́вный. сла́ва всебл҃го́мꙋ твоемꙋ̀ совѣ́тꙋ, сла́ва смотре́нїю твоемꙋ̀: сла́ва снисхожде́нїю твоемꙋ̀, є҆ди́не чл҃вѣколю́бче.",
								type: "1",
								tone: "1",
							},
							{
								kind: "kontakion",
								text: "Всѣ́хъ гдⷭ҇и ѡ҆брѣ́занїе терпи́тъ, и҆ человѣ́чєскаѧ прегрѣшє́нїѧ ꙗ҆́кѡ бл҃гъ ѡ҆брѣ́зꙋетъ, дае́тъ сп҃се́нїе дне́сь мі́рꙋ: ра́дꙋетсѧ же въ вы́шнихъ и҆ созда́телевъ і҆ера́рхъ и҆ свѣтоно́сный, бж҃е́ственный таи́нникъ хрⷭ҇то́въ васі́лїй.",
								type: "1",
								tone: "3",
								podoben: "1",
							},
						],
					},
				],
			},
		],
		hymns: [],
	},
